"""Generate product-led project pages from the public catalog and real film stills."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
projects=json.loads((ROOT/'projects.json').read_text())
esc=lambda s:html.escape(str(s),quote=True)
theme="try{const t=localStorage.getItem('theme');if(t==='light'||t==='dark')document.documentElement.dataset.theme=t;}catch(e){}"
toggle="document.querySelector('.theme').addEventListener('click',()=>{const r=document.documentElement,d=r.dataset.theme?r.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;r.dataset.theme=d?'light':'dark';try{localStorage.setItem('theme',r.dataset.theme);}catch(e){}});const v=document.querySelector('video'),play=document.querySelector('.case-play');if(v&&play){v.controls=false;play.hidden=false;const start=()=>{v.controls=true;v.play().then(()=>{play.hidden=true;v.focus();}).catch(()=>v.focus());};play.addEventListener('click',start);document.querySelector('[data-watch]')?.addEventListener('click',start);v.addEventListener('play',()=>play.hidden=true);v.addEventListener('ended',()=>play.hidden=false);}"
for i,p in enumerate(projects):
 name=esc(p['name']);rev='?v='+p['imageRevision'] if p.get('imageRevision') else '';poster=f'../../media/cases/{p["id"]}-hero.jpg'+rev;nxt=projects[(i+1)%len(projects)]
 primary=next(((label,href) for label,href in p['links'] if label not in ['Code','Code archive','Evaluation PR','Production recipes','Releases','Film tools','Workflow source','Example film']),None)
 actions=f'<a class="primary" href="{esc(primary[1])}">{esc(primary[0])} &#8599;</a>' if primary else ''
 actions+=f'<button type="button" data-watch class="{"primary" if not primary else ""}">Watch film &#9654;</button>'
 actions+=''.join(f'<a href="{esc(href)}">{esc(label)} &#8599;</a>' for label,href in p['links'] if not primary or (label,href)!=primary)
 features=''.join(f'<article><h2>{esc(title)}</h2><p>{esc(body)}</p></article>' for title,body in p['details'])
 gallery=''.join(f'<figure><img src="../../media/cases/{p["id"]}-{j}.jpg{rev}" width="1280" height="720" loading="lazy" alt="{name}: frame from the project film"></figure>' for j in [1,2])
 media=f'<video controls playsinline preload="none" poster="{poster}" tabindex="0" aria-label="{name} film"><source src="../../media/{esc(p["film"])}" type="video/mp4"></video><button class="case-play" hidden type="button" aria-label="Play {name} film with sound">&#9654; Play film</button>'
 intro=p['summary'].split(' The portfolio footage')[0].split(' Flower Girls and Puzzle People are separate')[0]
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{name} - Vyas Sathya</title><meta name="description" content="{esc(p['summary'])}"><meta name="color-scheme" content="light dark"><link rel="icon" href="../../favicon.svg"><link rel="stylesheet" href="../../site.css"><link rel="stylesheet" href="../../identities.css{rev}"><link rel="stylesheet" href="../../case-pages.css"><script>{theme}</script></head><body class="case-shell identity-{p['id']}" style="--brand:{p['accent']}"><a class="skip" href="#project">Skip to project</a><header class="bar"><a class="mark" href="../../">VS<span>Vyas Sathya</span></a><nav aria-label="Main navigation"><a href="../../#work">Work</a><a href="../../#services">Services</a><a href="../../#contact">Start a project</a><button class="theme" aria-label="Switch light or dark appearance"><svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true"><circle cx="10" cy="10" r="7" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M10 3a7 7 0 0 1 0 14z" fill="currentColor"/></svg></button></nav></header>
<main class="product-main" id="project"><section class="product-hero"><div><p class="product-name">{name}</p><h1>{esc(p['tagline'])}</h1><p class="product-intro">{esc(intro)}</p><div class="product-actions">{actions}</div></div><div class="case-stage" id="film">{media}</div></section><section class="product-features" aria-label="Project features">{features}</section><section class="product-gallery" aria-label="A closer look">{gallery}</section><details class="product-detail"><summary>Project details</summary><dl><div><dt>My contribution</dt><dd>{esc(p['contribution'])}</dd></div><div><dt>Project status</dt><dd>{esc(p['state'])}</dd></div><div><dt>About the footage</dt><dd>{esc(p['filmNote'])}</dd></div></dl></details><nav class="product-more" aria-label="More work"><a href="../../#work/{p['group']}">&#8592; All work</a><a class="next-project" href="../{nxt['id']}/"><img src="../../media/{nxt['thumbnail']['wide']}" alt="" width="210" height="66"><span><small>Next project</small>{esc(nxt['name'])} &#8599;</span></a></nav></main><footer class="foot"><span>Vyas Sathya, 2026</span><a href="../../#contact">Start a project &#8599;</a></footer><script>{toggle}</script></body></html>'''
 out=ROOT/'work'/p['id'];out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(page,encoding='utf-8')
(ROOT/'catalog.js').write_text('// Generated from projects.json.\nconst PROJECTS = '+json.dumps(projects,ensure_ascii=True,separators=(',',':'))+';\n')
print(f'Built {len(projects)} product-led pages.')
